<?php
declare(strict_types=1); require __DIR__.'/config.php'; if(!isLoggedIn()){header('Location:auth.php');exit;} $id=(int)($_GET['id']??0);
$s=db()->prepare('SELECT p.*,c.title category_title FROM playlists p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.is_active=1');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Плейлист не найден');}
if($_SERVER['REQUEST_METHOD']==='POST'){ $body=trim($_POST['body']??'');if($body!==''&&strlen($body)<=1000)db()->prepare('INSERT INTO comments(playlist_id,user_id,body) VALUES(?,?,?)')->execute([$id,$_SESSION['user_id'],$body]);header('Location:playlist.php?id='.$id.'#comments');exit; }
$comments=db()->prepare('SELECT c.*,u.username,u.avatar_path FROM comments c JOIN users u ON u.id=c.user_id WHERE c.playlist_id=? ORDER BY c.id DESC');$comments->execute([$id]);$comments=$comments->fetchAll();
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($p['title'])?> — BOMBALA</title><link rel="stylesheet" href="styles.css"></head><body><header class="topbar"><a class="logo" href="index.php"><img src="assets/bombala-logo.png" alt="BOMBALA"></a><div class="head-space"></div><a class="header-link" href="profile.php">Профиль</a><a class="header-link" href="index.php?logout=1">Выйти</a></header><main class="detail"><a class="back" href="index.php">← К каталогу</a><section class="detail-card"><div class="detail-cover" style="--cover:<?=e($p['cover_color'])?>"><span><?=e($p['quality'])?></span><b><?=e($p['category_title'])?></b></div><div class="detail-info"><p class="eyebrow">IPTV ПЛЕЙЛИСТ</p><h1><?=e($p['title'])?></h1><p class="description"><?=e($p['description']??'')?></p><div class="detail-meta"><span><?= (int)$p['channels']?> каналов</span><span><?=e($p['quality'])?></span><span>Обновлено сегодня</span></div><div class="link-box"><label>M3U-ссылка для плеера</label><div><input id="url" value="<?=e($p['playlist_url'])?>" readonly><button class="copy" onclick="navigator.clipboard.writeText(document.getElementById('url').value);this.textContent='Скопировано'">Копировать</button></div></div></div></section><section id="comments" class="comments"><h2>Комментарии <span><?=count($comments)?></span></h2><form class="comment-form" method="post"><div class="comment-avatar"><?=e(strtoupper(substr($_SESSION['username'],0,1)))?></div><textarea name="body" maxlength="1000" placeholder="Напишите свой комментарий..." required></textarea><button>Отправить комментарий</button></form><?php foreach($comments as $c):?><article class="comment"><div class="comment-avatar"><?php if($c['avatar_path']):?><img src="<?=e($c['avatar_path'])?>" alt=""><?php else:?><?=e(strtoupper(substr($c['username'],0,1)))?><?php endif;?></div><div><header><b><?=e($c['username'])?></b><time><?=e(date('d.m.Y',strtotime($c['created_at'])))?></time></header><p><?=nl2br(e($c['body']))?></p></div></article><?php endforeach;?></section></main></body></html>
